const $=selector=>document.querySelector(selector),home=$('#home'),domainView=$('#domain'),gameView=$('#game');
let active=null,selected=null,placed=new Map(),order=[],currentDomain=null,score=0,streak=0,bestStreak=0,wrongAnswers=0,completed=false;
function show(view){home.classList.toggle('hidden',view!=='home');domainView.classList.toggle('hidden',view!=='domain');gameView.classList.toggle('hidden',view!=='game')}
function renderDomains(){const grid=$('#domains');grid.innerHTML='';for(const domain of domains){const button=document.createElement('button');button.className='domain';button.innerHTML=`<span class="tag ready">${domain.weight} of exam</span><b>${domain.name}</b><small>${domain.games.length} interactive drills · ${domain.desc}</small>`;button.onclick=()=>openDomain(domain.id);grid.append(button)}}
function openDomain(id){currentDomain=domains.find(domain=>domain.id===id);if(!currentDomain)return;$('#domainTitle').textContent=currentDomain.name;$('#domainDesc').textContent=currentDomain.desc;const grid=$('#moduleGrid');grid.innerHTML='';for(const key of currentDomain.games){const game=games[key],button=document.createElement('button');button.className='module';button.innerHTML=`<span class="tag ready">Interactive drill</span><b>${game.title}</b><small>${game.sub}</small>`;button.onclick=()=>start(key);grid.append(button)}show('domain')}
function start(key){active=games[key];placed.clear();selected=null;score=0;streak=0;bestStreak=0;wrongAnswers=0;completed=false;order=active.cards.map(([id,text,row,why,url,name,type,region])=>({id,text,row,why,url,name,type,region}));$('#title').textContent=active.title;$('#subtitle').textContent=active.sub;$('#brief').innerHTML=active.brief;$('#complete').innerHTML=active.complete;$('#complete').classList.remove('show');$('#memoryContent').innerHTML=active.memory||'';$('#memory').classList.toggle('hidden',!active.memory);$('#gameStatus').classList.toggle('hidden',!active.gameplay);$('#cardsTitle').textContent=active.inventory?'Subscription inventory':active.matchMode==='terms'?'Definition cards':active.matchMode==='scenarios'?'Scenario cards':'Selection pane';$('#cardsHelp').textContent=active.inventory?'Drag a workload from the inventory table into an RSV row. On touch, tap the resource, then tap a destination.':active.matchMode==='terms'?'Drag each definition to the Azure term it describes. Misses show a Learn explanation.':active.matchMode==='scenarios'?'Drag each request to the solution that best meets it. Misses show a Learn explanation.':'Drag an action into a row. On touch, tap a card and then tap a row.';$('#answerHelp').textContent=active.inventory?'Assign every resource to its matching vault, or to No RSV match. Correct placements earn XP.':active.matchMode==='terms'?'Match all 15 concepts. Use the limits and scope cues in each definition.':active.matchMode==='scenarios'?'Choose the narrowest Azure service that meets each request. Watch for legacy or out-of-scope choices.':'Build the sequence and place distractors in the reject row.';$('#headStep').textContent=active.inventory?'Backup destination':active.matchMode==='terms'?'Azure term':active.matchMode==='scenarios'?'Operator request':'Step';$('#headWhat').textContent=active.hideDescriptions?'':active.matchMode==='scenarios'?'Best-fit solution':'What belongs here';$('#headDrop').textContent=active.inventory?'Resources assigned':active.matchMode?'Match':'Drop action';$('#headWhat').classList.toggle('hidden',!!active.hideDescriptions);$('#feedback').className='feedback';$('#feedback').textContent=active.gameplay?'Place each card. The explanation appears only if your match is wrong.':'Read the scenario, then place each action. You can tap a card and tap a row on touch screens.';show('game');render()}
function render(){const cards=$('#cards'),rows=$('#rows');cards.innerHTML='';cards.classList.toggle('inventory',!!active.inventory);const available=order.filter(card=>!placed.has(card.id));if(active.inventory){const table=document.createElement('table');table.className='inventory-table';table.innerHTML='<thead><tr><th scope="col">Name</th><th scope="col">Type</th><th scope="col">Region</th></tr></thead>';const body=document.createElement('tbody');active.vaults.forEach(([name,type,region])=>{const tr=document.createElement('tr');[name,type,region].forEach(value=>{const td=document.createElement('td');td.textContent=value;tr.append(td)});tr.className='vault-inventory';body.append(tr)});available.forEach(item=>{const tr=document.createElement('tr'),name=document.createElement('td'),type=document.createElement('td'),region=document.createElement('td'),button=document.createElement('button');button.className='card resource-card'+(selected===item.id?' selected':'');button.textContent=item.name;button.draggable=true;button.setAttribute('aria-label',`${item.name}, ${item.type}, ${item.region}. Drag to an answer row or tap to select.`);button.addEventListener('dragstart',event=>{event.dataTransfer.setData('text/plain',item.id);button.classList.add('dragging')});button.addEventListener('dragend',()=>button.classList.remove('dragging'));button.onclick=()=>{selected=selected===item.id?null:item.id;render()};name.append(button);type.textContent=item.type;region.textContent=item.region;tr.append(name,type,region);body.append(tr)});table.append(body);cards.append(table);if(!available.length){const done=document.createElement('div');done.className='empty';done.textContent='Inventory sorted. Reset the challenge to play again.';cards.append(done)}}else{if(!available.length)cards.innerHTML='<div class="empty">All action cards have been placed. Reset or shuffle to try again.</div>';available.forEach(item=>{const button=document.createElement('button');button.className='card'+(selected===item.id?' selected':'');button.textContent=item.text;button.draggable=true;button.setAttribute('aria-label',`${item.text}. Drag to an answer row or tap to select.`);button.addEventListener('dragstart',event=>{event.dataTransfer.setData('text/plain',item.id);button.classList.add('dragging')});button.addEventListener('dragend',()=>button.classList.remove('dragging'));button.onclick=()=>{selected=selected===item.id?null:item.id;render()};cards.append(button)})}rows.innerHTML='';active.rows.forEach(([id,label,desc])=>{const tr=document.createElement('tr'),step=document.createElement('th'),what=document.createElement('td'),cell=document.createElement('td'),zone=document.createElement('div');tr.dataset.row=id;step.className='step';step.scope='row';step.textContent=label;what.textContent=desc;cell.className='drop-cell';zone.className='dropzone';zone.dataset.zone=id;const items=order.filter(card=>placed.get(card.id)===id);if(items.length){zone.classList.add('correct');zone.setAttribute('aria-label',`Correct: ${items.map(item=>item.name||item.text).join(', ')}`);items.forEach(item=>{const placedCard=document.createElement('div');placedCard.className='placed';placedCard.textContent=`✓ ${active.inventory?`${item.name} · ${item.type}`:item.text}`;zone.append(placedCard)})}else zone.textContent=active.inventory?'Drop resources here':'Drop the matching action here';zone.addEventListener('dragover',event=>{event.preventDefault();zone.classList.add('over')});zone.addEventListener('dragleave',()=>zone.classList.remove('over'));zone.addEventListener('drop',event=>{event.preventDefault();zone.classList.remove('over');place(event.dataTransfer.getData('text/plain'),id)});zone.onclick=()=>{if(selected)place(selected,id)};cell.append(zone);tr.append(step);if(!active.hideDescriptions)tr.append(what);tr.append(cell);rows.append(tr)});if(active.gameplay)updateChallengeStatus();const done=placed.size===order.length;$('#complete').classList.toggle('show',done);if(done&&active.gameplay&&!completed){completed=true;score+=active.completionBonus;updateChallengeStatus();const badge=active.badge||'Challenge';const replay=active.completionPath?`<br><span class="source-note">Play again: ${active.completionPath}</span>`:'';$('#complete').innerHTML=`<strong>${badge} badge unlocked!</strong> Challenge complete. +${active.completionBonus} completion XP · ${score} total XP · Best streak ${bestStreak} · ${wrongAnswers} incorrect matches.${replay}`;$('#complete').classList.add('show')}}
function updateChallengeStatus(){const percent=order.length?Math.round(placed.size/order.length*100):0;const unit=active.inventory?'resources sorted':active.matchMode==='terms'?'terms matched':active.matchMode==='scenarios'?'scenarios matched':'actions placed';$('#gameStatus').innerHTML=`<div class="score-chip"><strong>${score}</strong><span>XP</span></div><div class="streak-chip">🔥 ${streak} streak <span>best ${bestStreak}</span></div><div class="challenge-progress"><div><strong>${placed.size}/${order.length}</strong><span>${unit}</span></div><progress max="${order.length}" value="${placed.size}" aria-label="${percent}% complete"></progress></div>`}
function place(id,row){const item=order.find(card=>card.id===id);if(!item||placed.has(id))return;if(item.row===row){placed.set(id,row);selected=null;if(active.gameplay){streak++;bestStreak=Math.max(bestStreak,streak);score+=active.points;if(streak%3===0)score+=active.streakBonus;$('#feedback').className='feedback good';$('#feedback').textContent=`Correct placement · +${active.points}${streak%3===0?` XP · +${active.streakBonus} streak bonus`:''}. Keep the streak going.`}else if(active.quiet){$('#feedback').className='feedback good';$('#feedback').textContent='Correct placement.'}else{$('#feedback').className='feedback good';$('#feedback').innerHTML=`Correct. ${item.why} <a href="${item.url}" target="_blank" rel="noopener noreferrer">Microsoft Learn</a>.`}render()}else{selected=null;if(active.gameplay){streak=0;wrongAnswers++}const zone=document.querySelector(`[data-zone="${row}"]`);zone.classList.remove('wrong');void zone.offsetWidth;zone.classList.add('wrong');const expected=order.find(card=>card.row===row);$('#feedback').className='feedback bad';$('#feedback').innerHTML=`Not this destination. “${active.inventory?item.name:item.text}” returned to the selection pane. ${item.why} <a href="${item.url}" target="_blank" rel="noopener noreferrer">Microsoft Learn</a>.`;if(!active.inventory){const destination=active.rows.find(entry=>entry[0]===row)?.[1];if(destination)$('#feedback').insertAdjacentHTML('beforeend',`<br><span class="source-note">This destination is “${destination}.” <a href="${item.url}" target="_blank" rel="noopener noreferrer">Microsoft Learn</a>.</span>`)}render()}}
renderDomains();$('#homeBtn').onclick=()=>show('home');$('#storageBtn').onclick=()=>currentDomain?openDomain(currentDomain.id):show('home');$('#reset').onclick=()=>{placed.clear();selected=null;score=0;streak=0;bestStreak=0;wrongAnswers=0;completed=false;render();$('#feedback').className='feedback';$('#feedback').textContent=active.inventory?'Challenge reset. Place the resources using vault type and region.':'Drill reset. Start with the first step.'};$('#shuffle').onclick=()=>{order.sort(()=>Math.random()-.5);selected=null;render()};
